-- Release 1 (expand): thêm cột mới và giữ hai cột đồng bộ bằng trigger
-- V42__add_phone_number.sql
SET lock_timeout = '5s';
ALTER TABLE customers ADD COLUMN phone_number text;

CREATE FUNCTION customers_sync_phone() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.phone_number := COALESCE(NEW.phone_number, NEW.phone);
    NEW.phone := COALESCE(NEW.phone, NEW.phone_number);
  ELSIF NEW.phone IS DISTINCT FROM OLD.phone THEN        -- code cũ sửa cột cũ
    NEW.phone_number := NEW.phone;
  ELSIF NEW.phone_number IS DISTINCT FROM OLD.phone_number THEN  -- code mới sửa cột mới
    NEW.phone := NEW.phone_number;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER trg_customers_sync_phone BEFORE INSERT OR UPDATE ON customers
  FOR EACH ROW EXECUTE FUNCTION customers_sync_phone();

